<script lang="ts">import type { Finding as FindingType } from './types'; import { percent } from './types'; let { finding, problem = false }: { finding: FindingType; problem?: boolean } = $props();</script>
<article class="finding" id={'finding-' + finding.id} tabindex="-1"><div class="finding-head"><h3>{finding.axis}</h3><span class:alert={problem && ['critical', 'high'].includes(finding.severity)} class="badge">{problem ? finding.severity + ' priority' : 'Strength'}</span><span class="muted mono">{percent(finding.confidence)} confidence</span></div><p>{finding.claim}</p><p class="card-names">{finding.evidence.cards.map(c => c.name).join(' · ')}</p><div class="refs">{#each finding.evidence.fact_keys as key}<code>{key}</code>{/each}</div></article>
